### Line Profile Figure

Create line profile figure for negative risk indicators
(@fig-indicator-neg-profile) and positive risk indicators
(@fig-indicator-pos-profile).


::: {.cell}

```{.r .cell-code}
# Figure caption
fig_caption_line <- paste(
  "Note. Left y-axis (0\u20131) = binary indicators (probability of behavior).",
  "Right y-axis (0\u20133) = continuous indicators (within-class mean).",
  "Continuous values are rescaled to the primary axis for display;")

# Panel-building function
make_panel_line <- function(risk_label,
                             left_name = "", left_lim, left_breaks,
                             sec_transform, right_name = "", right_breaks) {

  df_line <- profile_long %>% filter(Risk == risk_label)

  ggplot(df_line, aes(x = Indicators, y = value_plot,
                       color = cluster, group = cluster)) +

    # ---- reference gridlines between indicators ----
    geom_vline(
      xintercept = seq(1.5, length(unique(df_line$Indicators)) - 0.5, by = 1),
      color      = "gray90",
      linewidth  = 0.4
    ) +

    # ---- line + point geoms ----
    geom_line(linewidth = 3) +
    geom_point(size = 4) +

    # ---- color scale ----
    scale_color_manual(values = indicator_colors, labels = cluster_labels,
                        name = NULL) +

    # ---- y-axis (primary + secondary) ----
    scale_y_continuous(
      limits   = left_lim,
      breaks   = left_breaks,
      labels   = number_format(accuracy = 0.1),
      expand   = expansion(mult = c(0, 0.03)),
      sec.axis = sec_axis(
        transform = sec_transform,
        name      = right_name,
        breaks    = right_breaks,
        labels    = number_format(accuracy = 0.1)
      )
    ) +

    # ---- labels ----
    labs(title = paste(risk_label, "Risk Indicators"), y = NULL,
         caption = fig_caption_line) +

    # ---- theme ----
    base_theme +
    theme(
      axis.text.x        = element_text(angle = 35, hjust = 1,
                                         size = axis_text_size),
      axis.title.y.right = element_text(size = axis_title_size,
                                         color = "gray40"),
      legend.position    = "none",
      plot.title         = element_text(size = title_size, face = "bold",
                                         hjust = 0.5),
      plot.margin        = margin(12, 0, 20, 85))
}

# Build panels

